SELECT student_no,student_name,student_name_kana,CONVERT(char(10),birth_date,23),gender_code,postal_code,prefecture_code,address_line1,address_line2,phone_number,email_address,CONVERT(char(10),admission_date,23),enrollment_status_code,CONVERT(char(10),enrollment_end_date,23),CONVERT(varchar(19),class_id),emergency_contact_name,relationship_code,emergency_phone_number,remarks,name_key,kana_key,CONVERT(varchar(19),row_version),CONVERT(varchar(32),updated_at,127),updated_by FROM dbo.m_student WHERE student_id=? AND is_deleted=0;
